#include<bits/stdc++.h>
#include<atcoder/dsu>

using namespace std;
using namespace atcoder;

int mem[2010][2010]={0};

int dx6[6]={-1,-1,0,0,1,1};
int dy6[6]={-1,0,-1,1,0,1};

int main(){
  int n;
  cin >> n;
  dsu uf(n+1);
  vector<int> x(n+1),y(n+1);
  for(int i=1;i<=n;i++){
    cin >> x[i] >> y[i];
    x[i]+=1005;y[i]+=1005;
    mem[x[i]][y[i]]=i;
  }
  for(int i=1;i<=n;i++){
    for(int k=0;k<6;k++){
      int nx=x[i]+dx6[k];
      int ny=y[i]+dy6[k];
      if(mem[nx][ny]>0){
        uf.merge(i,mem[nx][ny]);
      }
    }
  }
  int res=0;
  for(int i=1;i<=n;i++){
    if(uf.leader(i)==i){res++;}
  }
  cout << res << "\n";
  return 0;
}
